const seedContract={stages:['role-policy','load-modules'],errorNames:['error','Error','PrismaClientKnownRequestError'],codes:['UNCLASSIFIED_RUNTIME_TABLE','MODULE_NOT_FOUND','P2002','UNKNOWN']};
const seedLine=r=>'SCHOOL_TEACHER_SEED_DIAGNOSTIC '+JSON.stringify(r);
const seedFailure={schemaVersion:1,status:'FAILED',stage:'role-policy',errorName:'error',code:'UNCLASSIFIED_RUNTIME_TABLE'};
test('seed failure parser preserves only the shared fixed stage error name and code contract',()=>{assert.deepEqual(parseSeedDiagnostic('private raw before\n'+seedLine(seedFailure)+'\nprivate raw after',seedContract),seedFailure);const cjs={...seedFailure,stage:'load-modules',errorName:'Error',code:'MODULE_NOT_FOUND'};assert.deepEqual(parseSeedDiagnostic(seedLine(cjs),seedContract),cjs);const src=readFileSync(new URL('./school-teacher-checks.mjs',import.meta.url),'utf8');assert(src.includes("stage==='browser-fixture'&&result.status!==0?{seedDiagnostic:"));assert(src.includes('assert.equal(result.status,0,stage+'));assert(src.includes('seedDiagnosticContract}=createRequire'))});
test('seed failure parser rejects arbitrary messages keys values and credential bearing data',()=>{for(const bad of [{...seedFailure,message:'postgresql://user:secret@host/db'},{...seedFailure,code:'token=secret'},{...seedFailure,errorName:'Authorization: Bearer secret'},{...seedFailure,stage:'private/user/path'},{...seedFailure,status:'PASSED'}]){const safe=parseSeedDiagnostic(seedLine(bad),seedContract);assert.deepEqual(safe,{status:'INVALID_SAFE_DIAGNOSTIC'});assert(!JSON.stringify(safe).includes('secret'))}});
test('seed failure parser rejects missing malformed duplicate and overlong records without exposing raw stderr',()=>{assert.deepEqual(parseSeedDiagnostic('Error: secret password',seedContract),{status:'MISSING_SAFE_DIAGNOSTIC'});for(const raw of ['SCHOOL_TEACHER_SEED_DIAGNOSTIC {bad',seedLine(seedFailure)+'\n'+seedLine(seedFailure),seedLine({...seedFailure,code:'x'.repeat(1025)})])assert.deepEqual(parseSeedDiagnostic(raw,seedContract),{status:'INVALID_SAFE_DIAGNOSTIC'})});

